import { createHash, randomUUID } from 'node:crypto';
import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, rename, rm, stat } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import type { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { Transform } from 'node:stream';
import { badRequest, tooLarge } from '../domain/errors.js';
import { SNIFF_BYTES, type Sniffed, sniff } from './sniff.js';

/** Keys are generated by the server only: "<report uuid>/<attachment uuid>.<ext>". */
const KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}\.[a-z0-9]{2,5}$/;

export type StoredFile = { tmpPath: string; size: number; sha256: string; type: Sniffed };

/**
 * Attachments on the local disk (a Docker volume). Uploads stream to a temporary file first, so a broken or
 * oversized upload never leaves a half-written attachment behind.
 */
export class MediaStore {
  readonly root: string;
  constructor(dir: string, readonly maxBytes: number) {
    this.root = resolve(dir);
  }

  path(key: string): string {
    if (!KEY.test(key)) throw new Error(`invalid storage key ${key}`);
    const p = resolve(this.root, key);
    if (!p.startsWith(this.root + sep)) throw new Error(`storage key escapes the media directory: ${key}`);
    return p;
  }

  /** Stream an upload into a temporary file, checking the size limit and detecting the type from the first bytes. */
  async receive(body: Readable, declared?: string): Promise<StoredFile> {
    const tmpDir = join(this.root, '.tmp');
    await mkdir(tmpDir, { recursive: true });
    const tmpPath = join(tmpDir, randomUUID());
    const hash = createHash('sha256');
    let size = 0;
    let head = Buffer.alloc(0);
    let type: Sniffed | null = null;
    const max = this.maxBytes;
    const meter = new Transform({
      transform(chunk: Buffer, _enc, done) {
        size += chunk.length;
        if (size > max) return done(tooLarge(`the file is larger than the limit of ${Math.round(max / 1024 / 1024)} MB`));
        if (!type) {
          if (head.length < SNIFF_BYTES) head = Buffer.concat([head, chunk.subarray(0, SNIFF_BYTES - head.length)]);
          if (head.length >= SNIFF_BYTES || head.length >= 12) {
            type = sniff(head, declared);
            if (!type && head.length >= SNIFF_BYTES) {
              return done(badRequest('unsupported file type: upload a photo (JPEG, PNG, WebP, GIF, HEIC), a video (MP4, MOV, WebM) or audio (M4A, MP3, WebM, Ogg, WAV, AAC)'));
            }
          }
        }
        hash.update(chunk);
        done(null, chunk);
      },
    });
    try {
      await new Promise<void>((done, fail) => {
        const out = createWriteStream(tmpPath);
        let failed = false;
        // Never destroy the request on a refusal: the client must still get the 400/413 answer. Stop writing,
        // let the rest of the body drain, and the route closes the connection after replying.
        const stop = (e: unknown) => {
          if (failed) return;
          failed = true;
          body.unpipe(meter);
          body.resume();
          meter.destroy();
          out.destroy();
          fail(e);
        };
        body.on('error', stop);
        body.on('aborted', () => stop(badRequest('the upload was interrupted')));
        meter.on('error', stop);
        out.on('error', stop);
        out.on('finish', () => !failed && done());
        body.pipe(meter).pipe(out);
      });
      type ??= sniff(head, declared);
      if (size === 0) throw badRequest('the file is empty');
      if (!type) throw badRequest('unsupported file type: upload a photo, a video or audio');
      return { tmpPath, size, sha256: hash.digest('hex'), type };
    } catch (e) {
      await rm(tmpPath, { force: true });
      throw e;
    }
  }

  async commit(tmpPath: string, key: string): Promise<void> {
    const dest = this.path(key);
    await mkdir(dirname(dest), { recursive: true });
    await rename(tmpPath, dest);
  }

  async writeBuffer(key: string, data: Buffer): Promise<void> {
    const dest = this.path(key);
    await mkdir(dirname(dest), { recursive: true });
    const tmp = join(this.root, '.tmp', randomUUID());
    await mkdir(dirname(tmp), { recursive: true });
    await pipeline(async function* () { yield data; }, createWriteStream(tmp));
    await rename(tmp, dest);
  }

  async discard(tmpPath: string): Promise<void> {
    await rm(tmpPath, { force: true });
  }

  async remove(key: string): Promise<void> {
    await rm(this.path(key), { force: true });
  }

  /** Everything stored for one report (its directory). */
  async removeReport(reportId: string): Promise<void> {
    if (!/^[0-9a-f-]{36}$/.test(reportId)) throw new Error(`invalid report id ${reportId}`);
    await rm(join(this.root, reportId), { recursive: true, force: true });
  }

  async size(key: string): Promise<number | null> {
    try {
      return (await stat(this.path(key))).size;
    } catch {
      return null;
    }
  }

  open(key: string, range?: { start: number; end: number }): Readable {
    return createReadStream(this.path(key), range);
  }
}
